// brand.jsx — KAVO Grid logo lockup + nav helpers
(function () {
  const { Icon } = window;

  // Company logo as a Base64 data URL — embedded so it renders reliably inside
  // print-to-PDF documents (quotation + receipt) without an async image load.
  window.COMPANY_LOGO = "data:image/png;base64,";
  window.PPS_NAV = { home: '/', product: 'product.html' };
  const go = (k) => { window.location.href = window.PPS_NAV[k]; };
  window.ppsGo = go;

  // Peak / "pinnacle" mark — layered ascending summit with an amber cap.
  function PinnacleMark({ size = 24, peak = '#fff', cap = '#FFB020' }) {
    return (
      <svg width={size} height={size} viewBox="0 0 40 40" fill="none" style={{ display: 'block' }}>
        <path d="M20 7 L34 32 H25.5 L20 21 L14.5 32 H6 Z" fill={peak} />
        <path d="M20 7 L26 18 L20 16 L14 18 Z" fill={cap} />
      </svg>
    );
  }

  // Lockup: official KAVO Grid logo. Renders the white asset on dark
  // backgrounds (footer passes text:'#fff') and the black asset elsewhere.
  function Logo({ size = 38, text = '#0B1A33', onClick }) {
    const onDark = /fff|255/.test(String(text).toLowerCase());
    const src = onDark ? 'images/brand/kavo-logo-white.png' : 'images/brand/kavo-logo-black.png';
    return (
      <img
        src={src}
        alt="KAVO Grid"
        onClick={onClick}
        style={{ height: size * 1.12, width: 'auto', display: 'block', flexShrink: 0, cursor: onClick ? 'pointer' : 'default', userSelect: 'none' }}
      />
    );
  }

  window.PinnacleMark = PinnacleMark;
  window.PPSLogo = Logo;
})();
